"use client";

import { useState, useEffect } from "react";
import axios from "axios";
import { CheckCircle, AlertCircle, Loader2, X, Upload } from "lucide-react";

export default function AddQuantity({ product, onClose, onSuccess }) {
  const [formData, setFormData] = useState({
    quantity: "",
    expirationDate: product.expirationDate.split("T")[0],
    nameSupplier: "",
    DateBon: new Date().toISOString().split("T")[0],
    bon: null,
    type: "Bon de livraison",
  });
  const [suppliers, setSuppliers] = useState([]);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [previewImage, setPreviewImage] = useState(null);

  useEffect(() => {
    fetchSuppliers();
  }, []);

  const fetchSuppliers = async () => {
    setIsLoading(true);
    const token = localStorage.getItem("token");
    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/suppliers`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setSuppliers(response.data);
    } catch (err) {
      setError(err.response?.data?.message || "Erreur lors de la récupération des fournisseurs");
    } finally {
      setIsLoading(false);
    }
  };

  const handleChange = (e) => {
    const { name, value, files } = e.target;
    if (name === "bon" && files?.length > 0) {
      setFormData({ ...formData, bon: files[0] });
      const reader = new FileReader();
      reader.onloadend = () => setPreviewImage(reader.result);
      reader.readAsDataURL(files[0]);
    } else {
      setFormData({ ...formData, [name]: value });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setSuccess("");
    setIsSubmitting(true);

    const token = localStorage.getItem("token");

    try {
      const formDataToSend = new FormData();
      formDataToSend.append("quantity", formData.quantity);
      formDataToSend.append("expirationDate", formData.expirationDate);
      formDataToSend.append("nameSupplier", formData.nameSupplier);
      formDataToSend.append("DateBon", formData.DateBon);
      if (formData.bon) {
        formDataToSend.append("bon", formData.bon);
        formDataToSend.append("type", formData.type);
      }

      await axios.put(`${process.env.REACT_APP_API_URL}/api/products/add-quantity/${product._id}`, formDataToSend, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "multipart/form-data",
        },
      });
      setSuccess("Quantité ajoutée avec succès !");
      setTimeout(() => {
        onSuccess();
        onClose();
      }, 1500);
    } catch (err) {
      setError(err.response?.data?.message || "Erreur lors de l'ajout de la quantité");
      console.error("Erreur Frontend :", err.response?.data || err);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex justify-center items-center z-50 p-4">
      <div className="max-w-2xl w-full bg-white rounded-xl shadow-xl overflow-hidden">
        <div className="bg-gradient-to-r from-amber-50 to-amber-100 border-b relative p-6">
          <button onClick={onClose} className="absolute right-4 top-4 rounded-full p-1.5 bg-white/90 text-zinc-500 hover:text-zinc-700">
            <X className="h-5 w-5" />
          </button>
          <h2 className="text-2xl font-bold text-[#00717F]">Ajouter Quantité - {product.nameProduct}</h2>
        </div>
        {isLoading ? (
          <div className="flex justify-center items-center h-64">
            <div className="flex flex-col items-center gap-2">
              <Loader2 className="h-10 w-10 text-[#00717F] animate-spin" />
              <p className="text-[#00717F] text-sm font-medium">Chargement des données...</p>
            </div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Quantité Actuelle</label>
                <input type="number" value={product.quantity} disabled className="w-full px-4 py-2.5 border border-gray-300 rounded-lg bg-gray-100" />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Quantité à Ajouter</label>
                <input type="number" name="quantity" value={formData.quantity} onChange={handleChange} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" min="1" required />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Nouveau Total (Calculé)</label>
                <input type="text" value={(product.quantity + (parseInt(formData.quantity) || 0))} disabled className="w-full px-4 py-2.5 border border-gray-300 rounded-lg bg-gray-100" />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Unité</label>
                <input type="text" value={product.unity} disabled className="w-full px-4 py-2.5 border border-gray-300 rounded-lg bg-gray-100" />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Date d'Expiration</label>
                <input type="date" name="expirationDate" value={formData.expirationDate} onChange={handleChange} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" required />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Fournisseur</label>
                <select name="nameSupplier" value={formData.nameSupplier} onChange={handleChange} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" required>
                  <option value="">Sélectionner un fournisseur</option>
                  {suppliers.map((supplier) => (
                    <option key={supplier._id} value={`${supplier.firstName} ${supplier.lastName}`}>
                      {supplier.firstName} {supplier.lastName}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Date du Bon</label>
                <input type="date" name="DateBon" value={formData.DateBon} onChange={handleChange} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" required />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Type de Bon</label>
                <select name="type" value={formData.type} onChange={handleChange} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg">
                  <option value="Bon de livraison">Bon de livraison</option>
                  <option value="Bon de sortie">Bon de sortie</option>
                </select>
              </div>
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 mb-1">Bon</label>
                <div className="flex items-center justify-center w-full">
                  <label className="flex flex-col items-center justify-center w-full h-12 border-2 border-dashed border-gray-300 rounded-lg cursor-pointer bg-gray-50 hover:bg-gray-100">
                    <div className="flex flex-col items-center justify-center">
                      {previewImage ? (
                        <img src={previewImage} alt="Aperçu" className="h-10 object-contain" />
                      ) : (
                        <>
                          <Upload className="w-4 h-4 text-gray-500" />
                          <p className="text-sm text-gray-500">Cliquez ou glissez une image ici</p>
                        </>
                      )}
                    </div>
                    <input type="file" name="bon" accept="image/*" onChange={handleChange} className="hidden" />
                  </label>
                </div>
              </div>
            </div>

            {(error || success) && (
              <div className={`p-4 ${error ? "bg-red-50" : "bg-green-50"} border-l-4 ${error ? "border-red-500" : "border-green-500"} flex items-center gap-3`}>
                {error ? <AlertCircle className="h-5 w-5 text-red-500" /> : <CheckCircle className="h-5 w-5 text-green-500" />}
                <p className={`text-sm ${error ? "text-red-700" : "text-green-700"}`}>{error || success}</p>
              </div>
            )}

            <div className="flex justify-end gap-4">
              <button type="button" onClick={onClose} className="px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50">
                Annuler
              </button>
              <button type="submit" disabled={isSubmitting} className="px-4 py-2 bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white rounded-lg hover:opacity-90 flex items-center gap-2">
                {isSubmitting ? (
                  <>
                    <Loader2 className="h-4 w-4 animate-spin" /> Traitement...
                  </>
                ) : (
                  "Ajouter Quantité"
                )}
              </button>
            </div>
          </form>
        )}
      </div>
    </div>
  );
}
